from weather_sdk import WeatherClient, WeatherError, AuthenticationError, APIError

def get_weather_safely(location: str, api_key: str):
    """Get weather with comprehensive error handling."""
    try:
        with WeatherClient(api_key=api_key) as client:
            weather = client.get_current_weather(location)
            return {
                'success': True,
                'temperature': weather.temperature,
                'description': weather.description
            }

    except AuthenticationError as e:
        return {
            'success': False,
            'error': 'authentication',
            'message': f"API key issue: {e}"
        }

    except WeatherError as e:
        return {
            'success': False,
            'error': 'weather_data',
            'message': f"Weather data unavailable: {e}"
        }

    except APIError as e:
        return {
            'success': False,
            'error': 'api',
            'message': f"API error: {e}"
        }

    except Exception as e:
        return {
            'success': False,
            'error': 'unexpected',
            'message': f"Unexpected error: {e}"
        }

# Usage
result = get_weather_safely("Chicago, IL", "your-api-key")
if result['success']:
    print(f"Temperature: {result['temperature']}°F")
else:
    print(f"Error ({result['error']}): {result['message']}")
